"Урок 25. Нахождение части от целого": "25-دەرس. پۈتۈننىڭ قىسمىنى تېپىش",
"S = 1 500 : 15 = 100 га, а не 10 га.": "S = 1 500 : 15 = 100 گېكتار، 10 گېكتار ئەمەس.",
"S = 1 500 : 15 = 100 га, а не 10 га.": "S = 1 500 : 15 = 100 گېكتار، 10 گېكتار ئەمەس.",
"Время встречи измеряют в километрах.": "ئۇچرىشىش ۋاقتى كىلومېتر بىلەن ئۆلچىنىدۇ.",
"v уд. = v₁ − v₂ = 75 − 50 = 25 км/ч.": "v يىراق. = v₁ − v₂ = 75 − 50 = 25 كم/سائەت.",
"Полярная звезда находится на севере.": "قۇتۇپ يۇلتۇزى شىمالدا.",
"Неверно: 3 < 7, поэтому 3/10 < 7/10.": "خاتا: 3 < 7، شۇڭا 3/10 < 7/10.",
"Найди число, 7/10 которого равны 63.": "7/10 ى 63 كە تەڭ بولغان ساننى تاپ.",
"Урок 1. Зависимость между величинами": "1-دەرس. چوڭلۇقلار ئارىسىدىكى باغلىنىش",
