"Как выглядит на графике движения остановка?": "ھەرىكەت گرافىكىدا توختاش قانداق كۆرۈنىدۇ?",
"При движении навстречу скорости складывают.": "بىر-بىرىگە قارشى ھەرىكەتتە سۈرئەتلەر قوشۇلىدۇ.",
"Достаточно исключать неподходящие варианты.": "ماس كەلمەيدىغان ۋارىيانتلارنى چىقىرىۋەتسە يېتەرلىك.",
"1 = 8/8: числитель и знаменатель одинаковы.": "1 = 8/8: سۈرەت بىلەن مەخرەج ئوخشاش.",
"Если 2/9 числа равны 18, то число равно 81.": "ئەگەر ساننىڭ 2/9 ى 18 گە تەڭ بولسا، سان 81 گە تەڭ.",
"Радиус окружности 6 см. Чему равен диаметр?": "چەمبەرنىڭ رادىئۇسى 6 سم. دىئامېتىرى نېمىگە تەڭ?",
"v уд. = 40 : 2 = 20 км/ч. 65 + 20 = 85 км/ч.": "v يىراقلىشىش = 40 : 2 = 20 كم/سائەت. 65 + 20 = 85 كم/سائەت.",
"«x < 3» — истинное высказывание при любом x.": "«x < 3» — ھەرقانداق x تە ھەقىقىي بايان.",
"Радиус окружности 15 см. Чему равен диаметр?": "چەمبەرنىڭ رادىئۇسى 15 سم. دىئامېتىرى نېمىگە تەڭ?",
"Два катера плывут друг к другу: 24 и 16 км/ч": "ئىككى كاتېر بىر-بىرىگە قاراپ ئۈزىدۇ: 24 ۋە 16 كم/سائەت",
"По вертикальной оси откладывают расстояние S.": "ۋېرتىكال ئوقتا ئارىلىق S نى بەلگىلەيدۇ.",
"Верное равенство — это истинное высказывание.": "توغرا تەڭلىك — ھەقىقىي بايان.",
"В неделе 7 дней, поэтому высказывание ложное.": "ھەپتىدە 7 كۈن بار، شۇڭا بايان يالغان.",
