"При скорости 60 км/ч за 3 часа проедут 200 км.": "سۈرئىتى 60 كم/سائەت بولسا، 3 سائەتتە 200 كم يول ماڭىدۇ.",
"Нельзя делить метры на километры без перевода.": "مېتىرنى كىلومېتىرغا ئايلاندۇرماي بۆلۈشكە بولمايدۇ.",
