"сумма больше 1: 5/6 + 4/6 (9/6 — неправильная)": "يىغىندى 1 دىن چوڭ: 5/6 + 4/6 (9/6 — ناتوغرا كەسىر)",
"3 диаметров занимают 18 см: d = 18 : 3 = 6 см.": "3 دىئامېتىر 18 سم ئورۇن ئالىدۇ: d = 18 : 3 = 6 سم.",
"За 1 ч путь вырос с 0 до 15 км: 15 − 0 = 15 км.": "1 سائەتتە يول 0 دىن 15 كم گىچە ئۆستى: 15 − 0 = 15 كم.",
"Например, вместо времени ищем скорость второго.": "مەسىلەن، ۋاقىتنىڭ ئورنىغا ئىككىنچىسىنىڭ سۈرئىتىنى ئىزدەيمىز.",
