"круг: часть плоскости, ограниченная окружностью": "دائىرە: چەمبەر بىلەن چەكلەنگەن تەكشىلىكنىڭ قىسمى",
"половина длины отрезка, проходящего через центр": "مەركەزدىن ئۆتىدىغان كېسىندىنىڭ يېرىمى",
"Собрали 1 600 ц при 20 ц/га. Какая площадь поля?": "20 سەنتنېر/گېكتار بولغاندا 1 600 سەنتنېر ھوسۇل ئېلىندى. ئېتىزنىڭ يۈزى قانچە?",
"Собрали 1 600 ц при 20 ц/га. Какая площадь поля?": "20 سەنتنېر/گېكتار بولغاندا 1 600 سەنتنېر ھوسۇل ئېلىندى. ئېتىزنىڭ يۈزى قانچە?",
"Периметр прямоугольника 25 м на 16 м равен 82 м.": "25 م بىلەن 16 م لىك تىك تۆتبۇلۇڭلۇقنىڭ پېرىمېتىرى 82 م.",
