"Дробная черта разделяет числитель и знаменатель.": "كەسىر سىزىقى سۈرەت بىلەن مەخرەجنى ئايرىيدۇ.",
"4/4 = 1, значит, это всё число: 28 : 4 · 4 = 28.": "4/4 = 1، دېمەك، بۇ پۈتۈن سان: 28 : 4 · 4 = 28.",
"Если расстояние больше радиуса, точка вне круга.": "ئارىلىق رادىئۇستىن چوڭ بولسا، نۇقتا دائىرىدىن سىرتتا بولىدۇ.",
"1 т = 10 ц, поэтому 50 т/га = 50 · 10 = 500 ц/га.": "1 ت = 10 سەنتنېر، شۇڭا 50 ت/گېكتار = 50 · 10 = 500 سەنتنېر/گېكتار.",
"75 − 50 = 25, значит, скорость удаления 125 км/ч.": "75 − 50 = 25، دېمەك، يىراقلىشىش سۈرئىتى 125 كم/سائەت.",
"Истинно ли высказывание «Неверно, что 324 < 305»?": "«324 < 305 دېگەن خاتا» دېگەن ھۆكۈم راستمۇ?",
"3 + 5 = 8, значит, 8/11. Знаменатель остаётся 11.": "3 + 5 = 8، دېمەك، 8/11. مەخرەج 11 بولۇپ قالىدۇ.",
