"Цена = стоимость : количество. 2 100 : 3 = 700 тг.": "باھا = قىممەت : مىقدار. 2 100 : 3 = 700 تەڭگە.",
"Цена = стоимость : количество. 2 100 : 3 = 700 тг.": "باھا = قىممەت : مىقدار. 2 100 : 3 = 700 تەڭگە.",
