"Расстояние от дома по минутам: 500 м, 500 м, 500 м": "ئۆيدىن ئارىلىق مىنۇت بويىچە: 500 م، 500 م، 500 م",
"Расстояние от дома по минутам: 600 м, 450 м, 300 м": "ئۆيدىن ئارىلىق مىنۇت بويىچە: 600 م، 450 م، 300 م",
