"смешанное число: 2 1/3 (целая часть 2 и дробь 1/3)": "ئارىلاش سان: 2 1/3 (پۈتۈن قىسمى 2 ۋە كەسىر 1/3)",
"на сколько метров сокращается расстояние за минуту": "بىر مىنۇتتا ئارىلىق قانچە مېتىر قىسقىرايدۇ",
"v уд. = 200 − 150 = 50 м/мин. t = 400 : 50 = 8 мин.": "v يىراق = 200 − 150 = 50 م/مىنۇت. t = 400 : 50 = 8 مىنۇت.",
