"Раздели число на знаменатель и умножь на числитель.": "ساننى مەخرەجگە بۆل ۋە سۈرەتكە كۆپەيت.",
"Расстояние то же, скорость выросла. Что со временем?": "ئارىلىق ئوخشاش، سۈرئەت ئاشتى. ۋاقىت قانداق بولىدۇ?",
